/**
 * Analyze frontend code structure and identify opportunities for animation enhancements
 */
export async function analyzeFrontendCode(args) {
  const { 
    code, 
    framework = 'react', 
    codeType = 'component' 
  } = args;

  try {
    const analysis = analyzeCodeStructure(code, framework, codeType);
    const opportunities = identifyAnimationOpportunities(analysis);
    const recommendations = generateRecommendations(opportunities, framework);

    const responseText = formatAnalysisResponse(analysis, opportunities, recommendations);

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error analyzing code: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Analyze code structure and extract key information
 */
function analyzeCodeStructure(code, framework, codeType) {
  const analysis = {
    framework,
    codeType,
    elements: [],
    interactions: [],
    layout: 'unknown',
    complexity: 'medium',
    techStack: detectTechStack(code),
    components: extractComponents(code),
    styling: detectStylingApproach(code)
  };

  // Detect UI elements
  analysis.elements = detectUIElements(code);
  
  // Detect interactions
  analysis.interactions = detectInteractions(code);
  
  // Detect layout type
  analysis.layout = detectLayoutType(code);
  
  // Assess complexity
  analysis.complexity = assessComplexity(code);

  return analysis;
}

/**
 * Detect technology stack from code
 */
function detectTechStack(code) {
  const indicators = {
    typescript: /\.tsx?|interface\s+\w+|type\s+\w+\s*=/.test(code),
    tailwind: /className=["'][^"']*(?:flex|grid|bg-|text-|p-|m-|w-|h-)/.test(code),
    styledComponents: /styled\.\w+|css`/.test(code),
    emotion: /@emotion|css\s*=/.test(code),
    css: /\.css|\.scss|\.sass/.test(code) || !(/className=/.test(code))
  };

  if (indicators.typescript && indicators.tailwind) return 'ts-tailwind';
  if (indicators.typescript) return 'ts-css';
  if (indicators.tailwind) return 'js-tailwind';
  return 'js-css';
}

/**
 * Extract React components from code
 */
function extractComponents(code) {
  const components = [];
  
  // Function components
  const functionComponents = code.match(/(?:function|const)\s+(\w+)\s*(?:\(|\s*=\s*\()/g);
  if (functionComponents) {
    functionComponents.forEach(match => {
      const name = match.match(/(?:function|const)\s+(\w+)/)[1];
      if (name && name[0] === name[0].toUpperCase()) {
        components.push({ name, type: 'function' });
      }
    });
  }

  // Class components
  const classComponents = code.match(/class\s+(\w+)\s+extends/g);
  if (classComponents) {
    classComponents.forEach(match => {
      const name = match.match(/class\s+(\w+)/)[1];
      components.push({ name, type: 'class' });
    });
  }

  return components;
}

/**
 * Detect styling approach
 */
function detectStylingApproach(code) {
  if (/className=["'][^"']*(?:flex|grid|bg-|text-)/.test(code)) return 'tailwind';
  if (/styled\.\w+|css`/.test(code)) return 'styled-components';
  if (/@emotion|css\s*=/.test(code)) return 'emotion';
  if (/\.module\.css/.test(code)) return 'css-modules';
  return 'css';
}

/**
 * Detect UI elements that could benefit from animations
 */
function detectUIElements(code) {
  const elements = [];
  
  const patterns = {
    buttons: /<button|<Button|onClick/g,
    cards: /<div[^>]*(?:card|Card)|className=["'][^"']*card/g,
    lists: /<ul|<ol|<li|\.map\(/g,
    modals: /modal|Modal|dialog|Dialog/g,
    forms: /<form|<input|<textarea|<select/g,
    navigation: /<nav|navbar|menu|Menu/g,
    images: /<img|<Image/g,
    headers: /<h[1-6]|<header|<Header/g,
    loading: /loading|Loading|spinner|Spinner/g,
    tabs: /tab|Tab|tabpanel/g
  };

  Object.entries(patterns).forEach(([type, pattern]) => {
    const matches = code.match(pattern);
    if (matches) {
      elements.push({
        type,
        count: matches.length,
        animationPotential: getAnimationPotential(type)
      });
    }
  });

  return elements;
}

/**
 * Detect user interactions
 */
function detectInteractions(code) {
  const interactions = [];
  
  const patterns = {
    click: /onClick|click/g,
    hover: /onMouseEnter|onMouseLeave|hover/g,
    focus: /onFocus|onBlur|focus/g,
    scroll: /onScroll|scroll/g,
    drag: /onDrag|drag/g,
    touch: /onTouch|touch/g
  };

  Object.entries(patterns).forEach(([type, pattern]) => {
    const matches = code.match(pattern);
    if (matches) {
      interactions.push({
        type,
        count: matches.length
      });
    }
  });

  return interactions;
}

/**
 * Detect layout type
 */
function detectLayoutType(code) {
  if (/grid|Grid|display:\s*grid/.test(code)) return 'grid';
  if (/flex|Flex|display:\s*flex/.test(code)) return 'flexbox';
  if (/absolute|fixed|relative/.test(code)) return 'positioned';
  return 'flow';
}

/**
 * Assess code complexity
 */
function assessComplexity(code) {
  const lines = code.split('\n').length;
  const components = (code.match(/(?:function|const|class)\s+\w+/g) || []).length;
  const interactions = (code.match(/on\w+|click|hover/g) || []).length;
  
  const score = lines * 0.1 + components * 5 + interactions * 2;
  
  if (score < 50) return 'simple';
  if (score < 150) return 'medium';
  return 'complex';
}

/**
 * Get animation potential for element type
 */
function getAnimationPotential(elementType) {
  const potentials = {
    buttons: 'high',
    cards: 'very-high',
    lists: 'high',
    modals: 'very-high',
    forms: 'medium',
    navigation: 'high',
    images: 'medium',
    headers: 'medium',
    loading: 'very-high',
    tabs: 'high'
  };
  
  return potentials[elementType] || 'low';
}

/**
 * Identify specific animation opportunities
 */
function identifyAnimationOpportunities(analysis) {
  const opportunities = [];

  // High-potential elements
  analysis.elements.forEach(element => {
    if (element.animationPotential === 'very-high') {
      opportunities.push({
        type: 'element-enhancement',
        target: element.type,
        priority: 'high',
        suggestion: getElementSuggestion(element.type),
        components: getRecommendedComponents(element.type)
      });
    }
  });

  // Interaction-based opportunities
  analysis.interactions.forEach(interaction => {
    opportunities.push({
      type: 'interaction-enhancement',
      target: interaction.type,
      priority: 'medium',
      suggestion: getInteractionSuggestion(interaction.type),
      components: getInteractionComponents(interaction.type)
    });
  });

  // Layout-based opportunities
  if (analysis.layout === 'grid' || analysis.layout === 'flexbox') {
    opportunities.push({
      type: 'layout-enhancement',
      target: analysis.layout,
      priority: 'medium',
      suggestion: `Add staggered animations for ${analysis.layout} items`,
      components: ['masonry', 'magic-bento', 'chroma-grid']
    });
  }

  return opportunities;
}

/**
 * Get suggestion for element type
 */
function getElementSuggestion(elementType) {
  const suggestions = {
    buttons: 'Add hover effects and click animations for better user feedback',
    cards: 'Implement card hover effects, stacking, or spotlight animations',
    lists: 'Add staggered entrance animations and smooth transitions',
    modals: 'Enhance with smooth entrance/exit animations and backdrop effects',
    loading: 'Replace basic loading with engaging animated components',
    tabs: 'Add smooth tab switching animations and active state indicators'
  };
  
  return suggestions[elementType] || `Add animations to enhance ${elementType}`;
}

/**
 * Get recommended components for element type
 */
function getRecommendedComponents(elementType) {
  const recommendations = {
    buttons: ['bounce-cards', 'elastic-slider'],
    cards: ['spotlight-card', 'tilted-card', 'decay-card', 'stack'],
    lists: ['infinite-scroll', 'masonry', 'rolling-gallery'],
    modals: ['fluid-glass', 'spotlight-card'],
    loading: ['orb', 'particles', 'lightning'],
    tabs: ['infinite-menu', 'dock']
  };
  
  return recommendations[elementType] || [];
}

/**
 * Get suggestion for interaction type
 */
function getInteractionSuggestion(interactionType) {
  const suggestions = {
    click: 'Add satisfying click animations and state transitions',
    hover: 'Implement smooth hover effects and micro-interactions',
    scroll: 'Add scroll-triggered animations and parallax effects',
    drag: 'Enhance drag interactions with physics-based animations'
  };
  
  return suggestions[interactionType] || `Enhance ${interactionType} interactions`;
}

/**
 * Get components for interaction type
 */
function getInteractionComponents(interactionType) {
  const components = {
    click: ['bounce-cards', 'elastic-slider', 'card-swap'],
    hover: ['spotlight-card', 'tilted-card', 'dock'],
    scroll: ['infinite-scroll', 'ripple-grid', 'beams'],
    drag: ['stack', 'elastic-slider']
  };
  
  return components[interactionType] || [];
}

/**
 * Generate recommendations based on opportunities
 */
function generateRecommendations(opportunities, framework) {
  return opportunities.map(opp => ({
    ...opp,
    implementation: getImplementationAdvice(opp, framework),
    effort: getEffortEstimate(opp),
    impact: getImpactEstimate(opp)
  }));
}

/**
 * Get implementation advice
 */
function getImplementationAdvice(opportunity, framework) {
  const advice = {
    'element-enhancement': `Replace or wrap existing ${opportunity.target} with React Bits components`,
    'interaction-enhancement': `Add React Bits animations to ${opportunity.target} handlers`,
    'layout-enhancement': `Integrate React Bits layout components for ${opportunity.target}`
  };
  
  return advice[opportunity.type] || 'Integrate React Bits components';
}

/**
 * Get effort estimate
 */
function getEffortEstimate(opportunity) {
  const efforts = {
    'element-enhancement': 'low',
    'interaction-enhancement': 'medium',
    'layout-enhancement': 'medium'
  };
  
  return efforts[opportunity.type] || 'medium';
}

/**
 * Get impact estimate
 */
function getImpactEstimate(opportunity) {
  const impacts = {
    high: 'high',
    medium: 'medium',
    low: 'low'
  };
  
  return impacts[opportunity.priority] || 'medium';
}

/**
 * Format analysis response
 */
function formatAnalysisResponse(analysis, opportunities, recommendations) {
  let output = `# Frontend Code Analysis Report\n\n`;
  
  // Basic info
  output += `**Framework:** ${analysis.framework}\n`;
  output += `**Code Type:** ${analysis.codeType}\n`;
  output += `**Tech Stack:** ${analysis.techStack}\n`;
  output += `**Complexity:** ${analysis.complexity}\n`;
  output += `**Layout Type:** ${analysis.layout}\n`;
  output += `**Styling:** ${analysis.styling}\n\n`;

  // Components found
  if (analysis.components.length > 0) {
    output += `## Components Found\n\n`;
    analysis.components.forEach(comp => {
      output += `- **${comp.name}** (${comp.type})\n`;
    });
    output += '\n';
  }

  // UI Elements
  output += `## UI Elements Analysis\n\n`;
  analysis.elements.forEach(element => {
    output += `- **${element.type}**: ${element.count} instances (${element.animationPotential} animation potential)\n`;
  });
  output += '\n';

  // Interactions
  if (analysis.interactions.length > 0) {
    output += `## Interactions Detected\n\n`;
    analysis.interactions.forEach(interaction => {
      output += `- **${interaction.type}**: ${interaction.count} instances\n`;
    });
    output += '\n';
  }

  // Opportunities
  output += `## Animation Opportunities\n\n`;
  recommendations.forEach((rec, index) => {
    output += `### ${index + 1}. ${rec.target} Enhancement\n`;
    output += `**Priority:** ${rec.priority}\n`;
    output += `**Effort:** ${rec.effort}\n`;
    output += `**Impact:** ${rec.impact}\n`;
    output += `**Suggestion:** ${rec.suggestion}\n`;
    output += `**Recommended Components:** ${rec.components.join(', ')}\n`;
    output += `**Implementation:** ${rec.implementation}\n\n`;
  });

  // Next steps
  output += `## Next Steps\n\n`;
  output += `1. **Get specific recommendations**: Use \`recommend-animations\` with your requirements\n`;
  output += `2. **Get component code**: Use \`get-react-bits-component\` for any recommended component\n`;
  output += `3. **Generate integration code**: Use \`generate-integration-code\` to see how to integrate\n`;
  output += `4. **Complete optimization**: Use \`optimize-frontend-with-animations\` for full solution\n`;

  return output;
}
